import re
from collections import Counter
from pathlib import Path

URL_RE = re.compile(r"https?://\S+", re.IGNORECASE)
HOST_RE = re.compile(r"^https?://([^/:]+)", re.IGNORECASE)


def домен(адреса):
    m = HOST_RE.match(адреса)
    if not m:
        return None
    d = m.group(1).lower()
    if d.startswith("www."):
        d = d[4:]
    return d or None


def main():
    шлях = Path("дані") / "запити.log"
